    dict(id='TN10-F3', mid='10', section='privacy', stem='transplant-nurse-10-data-privacy-principles-channels', scaffold='D', size='1672 × 941', title='Sensitive health data: three principles, approved channels only', content='Data Privacy Act principles for sensitive health information, role-based access, and approved versus unapproved channels', alt='Reference card of the three Data Privacy Act principles for health data, role-based access for registry, claims and donor records, and approved versus unapproved channels for sharing.', desc='Health information is sensitive personal information: collect only what the purpose needs, give access by role, and share only through approved channels.', abbrevs=[]),
