    dict(id='TN11-F2', mid='11', section='measure', stem='transplant-nurse-11-trustworthy-measure-anatomy', scaffold='D', size='1672 × 941', title='Anatomy of a measure you can trust', content='Anatomy of a quality measure (numerator, denominator, exclusions, prespecified threshold, data source) using abnormal-result review time as the example', alt='Diagram of a quality measure as a fraction — abnormal results reviewed within 24 hours over all results meeting a prespecified threshold — with exclusions, three rules for trustworthy measurement and a note that review time is a surrogate.', desc='A measure is only as good as its definitions: prespecify the threshold, count real review rather than notification, and name the data source.', abbrevs=[]),
