    dict(id='TN12-F3', mid='12', section='marking', stem='transplant-nurse-12-marking-sheet-pass-standard', scaffold='D', size='1672 × 941', title='How the capstone is scored', content='Scoring structure: five observable behaviors per station scored 2/1/0, pass standard and critical errors', alt='Scoring card for the capstone simulation: five behaviors per station scored 2, 1 or 0, with pass requiring at least 32 of 40, at least 7 of 10 on every station and no critical error.', desc='A pass needs a strong total, no weak station and no critical error — safety behaviors cannot be averaged away.', abbrevs=[]),
